public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> results = new ArrayList<>();
    boolean[] used = new boolean[nums.length];
    backtrack(nums, used, new ArrayList<>(), results);
    return results;
}

private void backtrack(int[] nums, boolean[] used,
                       List<Integer> path, List<List<Integer>> results) {
    if (path.size() == nums.length) {
        results.add(new ArrayList<>(path));   // full-length leaf → record a COPY
        return;
    }
    for (int i = 0; i < nums.length; i++) {   // always from 0 — order matters
        if (used[i]) continue;                // skip elements already in the path
        used[i] = true;                       // choose
        path.add(nums[i]);
        backtrack(nums, used, path, results); // explore
        path.remove(path.size() - 1);         // un-choose: restore BOTH
        used[i] = false;
    }
}

